CREATE COLUMN TABLE "TEST_AP"."OGPC" ("AbsId" INTEGER CS_INT NOT NULL , "Code" NVARCHAR(6) NOT NULL , "Descr" NVARCHAR(100), "StateTax" NVARCHAR(1) DEFAULT 'N', "Prdcity" NVARCHAR(1) DEFAULT 'M', "SPEDCtgory" INTEGER CS_INT, PRIMARY KEY ("AbsId")) UNLOAD PRIORITY 5  AUTO MERGE ;
CREATE UNIQUE INDEX "OGPC_CODE" ON "TEST_AP"."OGPC" ( "Code" ASC )